If $n_1=n_2=1$ then the Hardy-Littlewood-Ingham formula
\begin{displaymath}
\int_T^{T+U} Z^2(t){\rm d}t=U\ln\frac{T}{2\pi}+2cU+\mathcal{O}(T^{1/2}\xi^5)
\end{displaymath}
follows from the A. Selberg's formula (\ref{1.5}) (comp. \cite{20}, p. 120).

Let us remind that the A. Selberg's formula (\ref{1.5}) played the main role in proving the fundamental Selberg's result
\begin{displaymath}
N_0(T+U)-N_0(T)>A(\epsilon)U\ln T
\end{displaymath}
where $N_0$ stands for the number of zeroes of the function $\zeta(1/2+it),\ t\in (0,T]$.

Let
\begin{equation} \label{2.4}
G_3(x)=\varphi_1(\mathring{G}_3(x)),\ G_4(y)=\varphi_1(\mathring{G}_4(y)) .
\end{equation}
Then we have
\begin{equation} \label{2.5}
\begin{split}
& \int_{\mathring{G}_3(x)}\left(\sum_{2\leq p\leq\xi}\frac{1}{\sqrt{p}}\cos(\varphi_1(t)\ln p)\right)Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t\sim \\
& \frac{2x}{\pi}U\ln P\ln\ln P,\ x\in (0,\pi/2] , \\
& \int_{\mathring{G}_4(y)}\left(\sum_{2\leq p\leq\xi}\frac{1}{\sqrt{p}}\cos(\varphi_1(t)\ln p)\right)Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t\sim \\
& \frac{2y}{\pi}U\ln P\ln\ln P,\ y\in (0,\pi/2] ,
\end{split}
\end{equation}

\begin{equation} \label{2.6}
\begin{split}
& \int_{\mathring{G}_3(x)}\left(\sum_{2\leq n\leq\xi}\frac{1}{\sqrt{n}}\cos(\varphi_1(t)\ln n)\right)Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t\sim \\
& \frac{1}{\pi}\left\{ \left(\frac{2\epsilon}{5}-\frac{\epsilon^2}{50}\right)x+\frac{\epsilon^2}{50}\sin x\right\}U\ln^2 P , \\
& \int_{\mathring{G}_4(y)}\left(\sum_{2\leq n\leq\xi}\frac{1}{\sqrt{n}}\cos(\varphi_1(t)\ln n)\right)Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t\sim \\
& \frac{1}{\pi}\left\{ \left(\frac{2\epsilon}{5}-\frac{\epsilon^2}{50}\right)y-\frac{\epsilon^2}{50}\sin y\right\}U\ln^2 P ,
\end{split}
\end{equation}

\begin{equation} \label{2.7}
\begin{split}
& \int_{\mathring{G}_3(x)}\left(\sum_{2\leq n\leq\xi}\frac{d(n)}{\sqrt{n}}\cos(\varphi_1(t)\ln n)\right)Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t\sim \\
& \frac{\sin x}{2500\pi^3}U\ln^4P , \\
& \int_{\mathring{G}_4(y)}\left(\sum_{2\leq n\leq\xi}\frac{d(n)}{\sqrt{n}}\cos(\varphi_1(t)\ln n)\right)Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t\sim \\
& -\frac{\sin y}{2500\pi^3}U\ln^2P ,
\end{split}
\end{equation}
where
\begin{equation} \label{2.8}
t-\varphi_1(t) \sim (1-c)\pi(t),\ t\to\infty ,
\end{equation}
and $\pi(t)$ is the prime-counting function.

Let $T=\varphi_1(\mathring{T})$, $T+U=\varphi_1(\widering{T+U})$, (comp. (\ref{2.4})). Then from (\ref{2.8}), similarly to \cite{14}, (1.8), we obtain
\begin{displaymath}
\rho\{ [T,T+U]; [\mathring{T},\widering{T+U}]\}\sim (1-c)\pi(T);\ T+U<\mathring{T},
\end{displaymath}
where $\rho$ stands for the distance of the corresponding segments.

For every $T\geq T_0[\varphi_1]$ there are the values $\alpha_1(T), \alpha_2(T)\in \mathring{G}_3(\pi/2)\cup\mathring{G}_4(\pi/2)$ such that
\begin{equation} \label{3.4}
\sum_{2\leq p\leq \xi}\frac{1}{\sqrt{p}}\cos\{\varphi_1(\alpha_1(T))\ln p\}\sim \frac{2\ln P\ln\ln P}{\left|\zeta\left(\frac{1}{2}+i
\varphi_1(\alpha_2(T))\right)\right|^2},\ T\to\infty
\end{equation}
where $\varphi_1(\alpha_1(T)), \varphi_1(\alpha_2(T))\in \mathring{G}_3(\pi/2)\cup\mathring{G}_4(\pi/2)$.

For every $T\geq T_0[\varphi_1]$ there are the values $\alpha_3(T), \alpha_4(T)\in \mathring{G}_3(\pi/2)\cup\mathring{G}_4(\pi/2)$ such that
\begin{equation} \label{3.5}
\begin{split}
& \sum_{2\leq n\leq \xi}\frac{1}{\sqrt{n}}\cos\{\varphi_1(\alpha_3(T))\ln n\}\sim \\
& \sim \left(\frac{2\epsilon}{5}-\frac{\epsilon^2}{50}\right)\frac{\ln^2 P}
{\left|\zeta\left(\frac 12 +i\varphi_1(\alpha_4(T))\right)\right|^2},\ T\to\infty
\end{split}
\end{equation}
where $\varphi_1(\alpha_3(T)), \varphi_1(\alpha_4(T))\in G_3(\pi/2)\cup G_4(\pi/2)$.

\begin{equation} \label{4.1}
\begin{split}
& \left.\left\langle\sum_{2\leq n\leq \xi}\frac{d(n)}{\sqrt{n}}\cos\{\varphi_1(t)\ln n\}\right\rangle\right|_{\mathring{G}_3(x)}\sim \\
& \sim \frac{1}{2500\pi^2}\frac{\sin x}{x}\frac{\ln^4P}{\langle Z^2\{\varphi_1(t)\}\rangle|_{\mathring{G}_3(x)}} \\
& \left.\left\langle\sum_{2\leq n\leq \xi}\frac{d(n)}{\sqrt{n}}\cos\{\varphi_1(t)\ln n\}\right\rangle\right|_{\mathring{G}_4(y)}\sim \\
& \sim -\frac{1}{2500\pi^2}\frac{\sin y}{y}\frac{\ln^4P}{\langle Z^2\{\varphi_1(t)\}\rangle|_{\mathring{G}_4(y)}},\ T\to\infty
\end{split}
\end{equation}
where $\langle(\dots )\rangle|_{\mathring{G}_3(x)},\dots$ denote the mean-value of $(\dots)$ on $\mathring{G}_3(x), \dots$ .

It follows from (\ref{4.1}) that the short trigonometric sum
\begin{displaymath}
\sum_{2\leq n\leq \xi}\frac{d(n)}{\sqrt{n}}\cos\{t\ln n\},\ t\geq T_0[\varphi_1]
\end{displaymath}
has an infinitely many zeroes of the odd order.

\begin{equation} \label{5.1}
\begin{split}
& \int_{\mathring{G}_3^+(x)\cup \mathring{G}_4^+(x)}\left(\sum_{2\leq n\leq \xi}\frac{d(n)}{\sqrt{n}}\cos\{\varphi_1(t)\ln n\}\right)
Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t\sim \\
& \sim -\int_{\mathring{G}_3^-(x)\cup \mathring{G}_4^-(x)}\left(\sum_{2\leq n\leq \xi}\frac{d(n)}{\sqrt{n}}\cos\{\varphi_1(t)\ln n\}\right)
Z^2\{\varphi_1(t)\}\tilde{Z}^2(t){\rm d}t .
\end{split}
\end{equation}
